render_chart <- function(data, cfg, manifest) { size_col <- cfg$size %||% "size"; chart_validate_columns(data, list(x = cfg$x, y = cfg$y, size = size_col), c("x", "y", "size")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$x, y = cfg$y, size = size_col)) + ggplot2::geom_point(colour = cfg$color %||% "#0A84FF", alpha = 0.65) + ggplot2::scale_size_area() + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = cfg$x, y = cfg$y, size = size_col); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
